from analyze_ra import t_sf_two_sided
def pdf(x,v): return math.exp(math.lgamma((v+1)/2)-math.lgamma(v/2))/math.sqrt(v*math.pi)*(1+x*x/v)**(-(v+1)/2)
def tail(t,v,N=400000,U=200):
